# Loop until the queue is empty
while queue:
    # Get the current cell and its position in the grid
    row, col = queue.popleft()

    # If the current cell has not been visited before, mark it as visited
    if row not in visited or col not in visited:
        visited[row] = visited.get(row, set()) | {col}
        queue.append((row + 1, col + 1))

    # If the current cell is the last cell in the grid, return the path
